func (q *Queries) SettleOperatorChangeset(ctx context.Context, arg SettleOperatorChangesetParams) (OperatorChangeset, error) {
	row := q.db.QueryRow(ctx, settleOperatorChangeset,
		arg.Status,
		arg.Operations,
		arg.Error,
		arg.DecidedByMemberID,
		arg.AppliedAt,
		arg.RevertedAt,
		arg.Now,
		arg.WorkspaceID,
		arg.ID,
	)
	var i OperatorChangeset
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ThreadID,
		&i.MessageID,
		&i.MemberID,
		&i.ConversationID,
		&i.Title,
		&i.Reason,
		&i.Operations,
		&i.Status,
		&i.Auto,
		&i.Error,
		&i.DecidedByMemberID,
		&i.AppliedAt,
		&i.RevertedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const touchOperatorThread = `-- name: TouchOperatorThread :exec
UPDATE operator_threads
SET last_message_at = $1::timestamptz, updated_at = $1::timestamptz,
    title = CASE WHEN title = '' THEN $2 ELSE title END
WHERE workspace_id = $3 AND id = $4
`

type TouchOperatorThreadParams struct {
	Now         time.Time `json:"now"`
	Title       string    `json:"title"`
	WorkspaceID ids.UUID  `json:"workspace_id"`
	ID          ids.UUID  `json:"id"`
}

// TouchOperatorThread records a new message on the thread and names it
// when it had no title.
func (q *Queries) TouchOperatorThread(ctx context.Context, arg TouchOperatorThreadParams) error {
	_, err := q.db.Exec(ctx, touchOperatorThread,
		arg.Now,
		arg.Title,
		arg.WorkspaceID,
		arg.ID,
	)
	return err
}
